  const [pep1ShowB, setPep1ShowB] = useState(false);
  const [pep2ShowB, setPep2ShowB] = useState(false);
  const [showEditReasonsDialog, setShowEditReasonsDialog] = useState(false);
  const [newReasonInput, setNewReasonInput] = useState("");
  const [manualStopType, setManualStopType] = useState<"stop" | "pause">("stop");
  const [manualStopReason, setManualStopReason] = useState("");
  const [manualStopNotes, setManualStopNotes] = useState("");
  const [manualStopStart, setManualStopStart] = useState("");
  const [manualStopEnd, setManualStopEnd] = useState("");

  useEffect(() => {
    if (showStopDialog) {
      window.requestAnimationFrame(() => document.getElementById("stop-dialog-close")?.focus());
      return;
    }
    document.querySelector<HTMLButtonElement>('[data-testid="button-log-stoppage"]')?.focus();
  }, [showStopDialog]);

  // ── Screen casting mode ────────────────────────────────────────────────────
  const screenMode = useMemo(() => new URLSearchParams(window.location.search).get("screen"), []);
  const [showScreensDialog, setShowScreensDialog] = useState(false);
  // One-click Chromecast (Presentation API). Disabled on the cast display itself
  // (screenMode !== null) so TVs never try to reconnect/start presentations.
  const {
    supported: castSupported,
    casts: activeCasts,
    startCast,
    stopCast,
  } = usePresentationCast(screenMode === null);
  // ── Fullscreen / kiosk mode ────────────────────────────────────────────────
  const [isFullscreen, setIsFullscreen] = useState(false);
  useEffect(() => {
    const handler = () => setIsFullscreen(!!document.fullscreenElement);
    document.addEventListener("fullscreenchange", handler);
    return () => document.removeEventListener("fullscreenchange", handler);
  }, []);
  function toggleFullscreen() {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().catch(() => {});
    } else {
      document.exitFullscreen().catch(() => {});
    }
  }

  // ── Online / offline ───────────────────────────────────────────────────────
  const [isOnline, setIsOnline] = useState(() => navigator.onLine);
  useEffect(() => {
    const on = () => setIsOnline(true);
    const off = () => setIsOnline(false);
    window.addEventListener("online", on);
    window.addEventListener("offline", off);
    return () => { window.removeEventListener("online", on); window.removeEventListener("offline", off); };
  }, []);

  // Finished-case surplus is authoritative server data, not a day-state
  // overlay. Load it for every signed-in web session so Packaging can record a
  // new dated lot and Warehouse can explicitly allocate one before a run.

  // ── Server-write failure surface ───────────────────────────────────────────
  // The sync push and the inventory-consume write are both best-effort/optimistic
  // (they retry then give up). Previously a final failure was swallowed silently,
  // so the user had no idea their work wasn't saved server-side. Track the two
  // failure modes and surface a clear, dismissible banner + a red status dot.
  const [syncPushFailed, setSyncPushFailed] = useState(false);
  const [writeError, setWriteError] = useState<string | null>(null);
  const syncDate = todayStr();
  const [syncDiagnostics, setSyncDiagnostics] = useState<SyncDiagnostic[]>(() => loadSyncDiagnostics(syncDate));
  const [lastAcknowledgedAt, setLastAcknowledgedAt] = useState<number | null>(() => {
    const events = loadSyncDiagnostics(syncDate);
    return events.filter((event) => event.kind === "ack").at(-1)?.at ?? null;
  });
  const [syncPendingCount, setSyncPendingCount] = useState(0);
  const [syncFailedCount, setSyncFailedCount] = useState(() =>
    loadSyncDiagnostics(syncDate).filter((event) => event.kind === "failure" || event.kind === "stale").length,
  );
  const [syncRetryWaiting, setSyncRetryWaiting] = useState(false);
  const recordSyncEvent = (kind: SyncDiagnosticKind, message: string, response?: string, runId?: string) => {
    const event = recordSyncDiagnostic({ kind, at: Date.now(), date: syncDate, message, response, runId });
    setSyncDiagnostics((current) => [...current, event].slice(-20));
    if (kind === "ack") setLastAcknowledgedAt(event.at);
  };

  const exportSyncDiagnostics = () => {
    // The app can remain mounted while the local calendar date changes. Read
    // the date and its persisted events at export time instead of relying on
    // the values captured during the previous render.
    const reportDate = todayStr();
    const reportDiagnostics = loadSyncDiagnostics(reportDate);
    const reportMeasurements = loadSyncMeasurements(reportDate);
    const report = buildSyncDiagnosticReport({
      date: reportDate,
      status: syncStatus,
      lastAcknowledgedAt,
      pendingCount: syncPendingCount,
      failedCount: syncFailedCount,
      diagnostics: reportDiagnostics,
      measurements: reportMeasurements,
    });
    const blob = new Blob([JSON.stringify(report, null, 2)], { type: "application/json;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = `sync-diagnostic-history-${reportDate}.json`;
    anchor.click();
    URL.revokeObjectURL(url);
  };


  // ── Fetch scheduled future days for badge ──────────────────────────────────
  useEffect(() => {
    fetch(`/api/sync/scheduled?include=runs&today=${todayStr()}`).then(r => r.json()).then(d => setScheduledDays(normalizeScheduledDays(d))).catch(() => {});
  }, []);

  // ── Reorder runs dialog ────────────────────────────────────────────────────
