  const [mergeBfMode, setMergeBfMode] = useState<"brands" | "flavors">("brands");
  const [mergeBfBrand, setMergeBfBrand] = useState("");

  // Local (per-device) master-data change history for the undo trail.
  const [changeHistory, setChangeHistory] = useState<MasterDataChange[]>(() => loadChangeHistory());
  const [undoBusy, setUndoBusy] = useState(false);
  // Record a change (snapshot already taken before the edit) and refresh the list.
  const noteChange = useCallback(
    (type: MasterDataChangeType, description: string, before: Record<string, string>) => {
      recordMasterDataChange(type, description, before);
      setChangeHistory(loadChangeHistory());
    },
    [],
  );

  // ── One-time recipe-name consolidation into the server master-data pools ──
  // The run-form pickers union server pool names with legacy LOCAL name lists,
  // so old local-only entries ("Mystic", "Mystic Recipe", "mystic sauce") show
  // up in pickers but never in Manage Lists (which shows server pools only).
  // This migration, on a manager device: pushes every local-only name into the
  // right server pool (cheese-list names that are really mixes route to Mixes),
  // folds near-duplicate variants onto one canonical spelling (rewriting run
  // values + presets via the existing merge machinery, with tombstones so sync
  // can't resurrect them), then empties the legacy local lists. Marker-guarded;
  // re-armed on failure so it retries next mount. Names that can't safely land
  // on the server (ambiguous near-dups) are left in the local list untouched.
  const nameConsolidationRef = useRef(false);
  useEffect(() => {
    if (nameConsolidationRef.current || !canManageInventory) return;
    const MARKER = "run-calc-recipe-name-consolidation-v1";
    try {
      if (localStorage.getItem(MARKER)) { nameConsolidationRef.current = true; return; }
    } catch {}
    const localSauce = loadList(FRONTLINE_RECIPE_NAMES_KEY, []).filter((n) => !SEED_MIX_RECIPE_NAMES.has(n));
    const localDough = loadList(DOUGH_RECIPE_NAMES_KEY, []);
    const localCheeseAll = loadList(CHEESE_RECIPE_NAMES_KEY, []);
    const localMix = loadList(MIX_RECIPE_NAMES_KEY, []);
    // A fresh device may simply not have pulled its first sync yet. Don't set
    // the marker; the list states in the deps re-fire this effect when the
    // legacy lists actually arrive (and if they never do, there is no work).
    if (localSauce.length + localDough.length + localCheeseAll.length + localMix.length === 0) return;
    nameConsolidationRef.current = true;
    (async () => {
      const before = captureMasterDataSnapshot();
      const [saucePool, doughPool, mixPool, cheesePool] = await Promise.all([
        fetchNamedRecipes("sauce"),
        fetchNamedRecipes("dough"),
        fetchMixes(),
        fetchCheeseRecipes(),
      ]);
      // Saved local recipe rows keyed case-insensitively: used both to prefer
      // the variant that actually has a recipe as the canonical spelling and to
      // carry those rows along when a name is pushed to the server.
      const rowsCi = (entries: Array<[string, RecipeRow[] | undefined]>) => {
        const m = new Map<string, RecipeRow[]>();
        for (const [name, rows] of entries) {
          const k = name.trim().toLowerCase();
          if (k && rows && rows.length > 0 && !m.has(k)) m.set(k, rows);
        }
        return m;
      };
      const doughRows = rowsCi(Object.entries(loadDoughRecipePresets()).map(([n, p]) => [n, p?.rows]));
      const sauceRows = rowsCi(Object.entries(loadFrontlineRecipePresets()));
      const cheeseRows = rowsCi(Object.entries(loadCheeseRecipePresets()));
      const hasRows = (m: Map<string, RecipeRow[]>) => (n: string) =>
        (m.get(n.trim().toLowerCase())?.length ?? 0) > 0;
      // Legacy cheese-list names that are really mixes (same heuristic +
      // user-categorization-wins rule spec-import uses) route to the Mixes pool.
      const mixNamesLower = new Set(
        [...localMix, ...mixPool.map((m) => m.name)].map((n) => n.trim().toLowerCase()),
      );
      const cheeseAsMix: string[] = [];
      const localCheese: string[] = [];
      for (const n of localCheeseAll) {
        const rows = cheeseRows.get(n.trim().toLowerCase()) ?? [];
        (specImportCheeseRecipeIsMix(n, mixNamesLower, rows.length) ? cheeseAsMix : localCheese).push(n);
      }
      const cheeseOriginLower = new Set(cheeseAsMix.map((n) => n.trim().toLowerCase()));
      // Plan per pool: which local names are already on the server, which fold
      // onto an existing/canonical spelling, and which get added.
      const plans = {
        sauce: planNameConsolidation({
          localNames: localSauce,
          serverNames: saucePool.map((r) => r.name),
          genericTokens: ["sauce", "recipe"],
          preferAsCanonical: hasRows(sauceRows),
        }),
        dough: planNameConsolidation({
          localNames: localDough,
          serverNames: doughPool.map((r) => r.name),
          genericTokens: ["dough", "recipe"],
          preferAsCanonical: hasRows(doughRows),
        }),
        cheese: planNameConsolidation({
          localNames: localCheese,
          serverNames: cheesePool.map((r) => r.name),
          genericTokens: ["recipe"],
          preferAsCanonical: hasRows(cheeseRows),
        }),
        mixes: planNameConsolidation({
          localNames: [...localMix, ...cheeseAsMix],
          serverNames: mixPool.map((m) => m.name),
          genericTokens: ["recipe"],
          preferAsCanonical: hasRows(cheeseRows),
        }),
      };
      // Push planned additions into each server pool. The add helpers run their
      // own (narrower) near-dup matcher and may skip a candidate; reconcile by
      // re-planning skipped names against the final pool — matches become
      // renames, anything still unmatched stays in the local list (leftover).
      const leftovers = {
        sauce: new Set<string>(),
        dough: new Set<string>(),
        cheese: new Set<string>(),
        mixes: new Set<string>(),
      };
      const reconcile = (
        kind: keyof typeof plans,
        finalNames: string[],
        genericTokens: string[],
      ) => {
        const ci = new Set(finalNames.map((n) => n.trim().toLowerCase()));
        const missing = plans[kind].additions.filter((n) => !ci.has(n.trim().toLowerCase()));
        if (missing.length === 0) return;
        const follow = planNameConsolidation({
          localNames: missing,
          serverNames: finalNames,
          genericTokens,
        });
        Object.assign(plans[kind].renames, follow.renames);
        for (const n of follow.additions) leftovers[kind].add(n);
      };
      if (plans.sauce.additions.length > 0) {
        const drafts = plans.sauce.additions
          .map((n) => namedRecipeFromDraft({ name: n, components: sauceRows.get(n.trim().toLowerCase()) ?? [], idPrefix: "sauce" }))
          .filter((r): r is NamedRecipe => r !== null);
        const { added, updated, items } = await addNamedRecipesToServerIfAbsent("sauce", drafts, undefined, undefined, undefined, undefined, { upsertComponents: true });
        if (added > 0 || updated > 0) cycleCountQc.setQueryData(["sauceRecipes"], items);
        reconcile("sauce", items.map((r) => r.name), ["sauce", "recipe"]);
      }
      if (plans.dough.additions.length > 0) {
        const drafts = plans.dough.additions
          .map((n) => namedRecipeFromDraft({ name: n, components: doughRows.get(n.trim().toLowerCase()) ?? [], idPrefix: "dough" }))
          .filter((r): r is NamedRecipe => r !== null);
        const { added, updated, items } = await addNamedRecipesToServerIfAbsent("dough", drafts, undefined, undefined, undefined, undefined, { upsertComponents: true });
        if (added > 0 || updated > 0) cycleCountQc.setQueryData(["doughRecipes"], items);
        reconcile("dough", items.map((r) => r.name), ["dough", "recipe"]);
      }
      if (plans.cheese.additions.length > 0) {
        const drafts = plans.cheese.additions
          .map((n) => specCheeseDraftToRecipe({ name: n, brand: "", flavors: [], components: cheeseRows.get(n.trim().toLowerCase()) ?? [] }))
          .filter((r): r is CheeseRecipe => r !== null);
        const { merged, added } = addCheeseRecipesIfAbsentByName(cheesePool, drafts);
        let finalNames = cheesePool.map((r) => r.name);
        if (added > 0) {
          const saved = await saveCheeseRecipes(merged);
          cycleCountQc.setQueryData(["cheeseRecipes"], saved);
          finalNames = saved.map((r) => r.name);
        }
        reconcile("cheese", finalNames, ["recipe"]);
      }
      if (plans.mixes.additions.length > 0) {
        const drafts = plans.mixes.additions
          .map((n) => specMixDraftToMix({
            name: n,
            brand: "",
            flavor: "",
            components: (cheeseRows.get(n.trim().toLowerCase()) ?? []).map((r) => ({ ingredient: r.ingredient, perPizza: 0 })),
          }))
          .filter((m): m is Mix => m != null);
        const { merged, added } = addSpecMixesIfAbsent(mixPool, drafts);
        let finalNames = mixPool.map((m) => m.name);
        if (added > 0) {
          const saved = await saveMixes(merged);
          cycleCountQc.setQueryData(["mixes"], saved);
          finalNames = saved.map((m) => m.name);
        }
        reconcile("mixes", finalNames, ["recipe"]);
      }
      // Fold near-dup variants onto their canonical spelling through the same
      // machinery the Merge tab uses (rewrites run values, presets, list +
      // tombstones the merged-away names). Mix renames whose source came from
      // the legacy CHEESE list are also applied under "cheese" so cheese-side
      // references and the cheese list/tombstone namespace get rewritten too.
      const affectedRunIds: string[] = [];
      const applyRenames = (category: RecipeNameMergeCategory, renames: Record<string, string>) => {
        const map: MergeMap = {};
        for (const [src, tgt] of Object.entries(renames)) {
          if (src.trim().toLowerCase() !== tgt.trim().toLowerCase()) map[src] = tgt;
        }
        if (Object.keys(map).length === 0) return;
        affectedRunIds.push(...applyRecipeNameMerge(category, map));
      };
      applyRenames("sauce", plans.sauce.renames);
      applyRenames("dough", plans.dough.renames);
      applyRenames("cheese", plans.cheese.renames);
      applyRenames("mixes", plans.mixes.renames);
      const mixRenamesFromCheese = Object.fromEntries(
        Object.entries(plans.mixes.renames).filter(([src]) => cheeseOriginLower.has(src.trim().toLowerCase())),
      );
      applyRenames("cheese", mixRenamesFromCheese);
      // Empty the legacy local lists: every name is now either on the server
      // (alreadyPresent/addition), renamed away (tombstoned by the merge), or a
      // leftover we intentionally keep. Tombstone dropped names so the additive
      // sync union can't re-add them from a peer.
      const wipeCovered = (
        listKey: string,
        namespace: string,
        keep: Set<string>,
      ) => {
        const cur = loadList(listKey, []);
        const kept = cur.filter((n) => keep.has(n));
        const dropped = cur.filter((n) => !keep.has(n));
        if (dropped.length === 0) return;
        for (const n of dropped) tombstoneDeleted(namespace, n);
        saveList(listKey, kept);
      };
      const cheeseKeep = new Set([...leftovers.cheese, ...[...leftovers.mixes].filter((n) => cheeseOriginLower.has(n.trim().toLowerCase()))]);
      const mixKeep = new Set([...leftovers.mixes].filter((n) => !cheeseOriginLower.has(n.trim().toLowerCase())));
      // Namespace strings mirror RECIPE_NAME_MERGE_STORE in storage.ts so these
      // tombstones land in the same per-list namespace the merge path uses.
      wipeCovered(FRONTLINE_RECIPE_NAMES_KEY, "frontlineRecipeNames", leftovers.sauce);
      wipeCovered(DOUGH_RECIPE_NAMES_KEY, "doughRecipeNames", leftovers.dough);
      wipeCovered(CHEESE_RECIPE_NAMES_KEY, "cheeseRecipeNames", cheeseKeep);
      wipeCovered(MIX_RECIPE_NAMES_KEY, "mixRecipeNames", mixKeep);
      // Advance the edit stamp on every run the renames re-pointed so the sync
      // push below wins the per-run lost-update guard on every peer.
      if (affectedRunIds.length > 0) {
        const stamp = Date.now();
        const upd = loadRunValuesUpdated();
        for (const id of affectedRunIds) upd[id] = stamp;
        saveRunValuesUpdated(upd);
      }
      refreshAfterMerge();
      // Push immediately so an incoming sync-pull's additive union can't
      // resurrect the wiped names on this device. Best-effort.
      try {
        await pushTodayCanonical(buildSyncPayload(loadDayState()));
      } catch {}
      noteChange(
        "merge",
        "Consolidated legacy recipe names into the shared Manage Lists pools",
        before,
      );
      try { localStorage.setItem(MARKER, "1"); } catch {}
    })().catch(() => { nameConsolidationRef.current = false; });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [canManageInventory, frontlineRecipeNames, doughRecipeNames, cheeseRecipeNames, mixRecipeNames, cycleCountQc, noteChange]);

  const dedupSorted = (all: string[]) => {
    const seen = new Set<string>();
    const out: string[] = [];
    for (const n of all) {
      const key = n.toLowerCase();
      if (!seen.has(key)) { seen.add(key); out.push(n); }
    }
    return out.sort((a, b) => a.localeCompare(b));
  };

  // The full mergeable universe: every master-data list whose values get
  // rewritten by an ingredient merge. Die types are intentionally EXCLUDED —
  // they are a distinct physical-tooling list (not an ingredient-name pool) and
  // the `dieType` selection field is no longer rewritten by a merge. Used by the
  // AI "Suggested merges" scan and the import auto-check, which look for
  // duplicates ACROSS categories (an imported recipe ingredient can duplicate a
  // standalone one). Brands/flavors are excluded (they have their own merge path).
  const mergeFullUniverse = useMemo(
    // The unified universe already unions every local master list PLUS the
    // server ingredient catalog and every server recipe pool's rows, so any
    // ingredient used anywhere is mergeable here.
    () => dedupSorted(unifiedIngredientUniverse),
    [unifiedIngredientUniverse],
  );

  // The names the manual source/target pickers offer, scoped to the selected
  // merge category so a merge stays within its own group. The merge engine is
  // still name-based and global — the tab only narrows what's pickable. On the
  // brand/flavor tab the universe is the brand list (brands mode) or one brand's
  // flavors (flavors mode).
  // ── Stale recipe references (all four recipe-name tabs) ───────────────────
  // Names still referenced by a run, profile, template, or history entry (or
  // held by a legacy synced local name list) that match NO server pool name
  // for the active recipe tab — e.g. a name whose pool row was merged/renamed/
  // re-imported while a device held a stale pick. The pickers always show the
  // current pick, so without this they were visible there but unfindable in
  // Merge — the merge rewrites every link field, which is exactly how a user
  // cleans one up. Cheese and mix picks share the app{n}CheeseRecipeName link
  // fields, so on those tabs a link name is only stale when it matches NEITHER
  // pool (the same stale name is offered on both tabs — either merge fixes it).
  const mergeStaleNames = useMemo(() => {
    const cat = mergeCategory;
    if (cat !== "mixes" && cat !== "dough" && cat !== "sauce" && cat !== "cheese") {
      return [] as string[];
    }
    // On the Mix Plan tab, factory MIX_SEED names count as "known" too: they are
    // locally seeded (not stale), unmergeable by the apply guardrail, and
    // would just be re-seeded if merged away — treating them as stale would
    // surface selectable-but-unmergeable rows.
    const mixSeedCi =
      cat === "mixes"
        ? new Set(MIX_SEED.mixRecipeNames.map((n) => n.trim().toLowerCase()))
        : null;
    const poolCi = new Set([
      ...(cat === "dough" ? serverDoughNames
        : cat === "sauce" ? serverSauceNames
        : [...serverCheeseNames, ...serverMixNames]
      ).map((n) => n.trim().toLowerCase()),
      ...(mixSeedCi ?? []),
    ]);
    let stale: string[] = [];
    try {
      stale = collectStaleRecipeLinkNames(
        collectMergeSurfaces().settingsObjects,
        poolCi,
        RECIPE_NAME_FIELDS_BY_CATEGORY[cat],
      );
    } catch (e) {
      // Never let a surface-scan failure blank the whole tab — but don't
      // swallow it silently either (a TDZ error hid here once).
      console.warn(`${cat} merge stale-name scan failed:`, e);
    }
    // The legacy local name lists still feed some pickers (e.g. the schedule
    // editor's Advanced selects) and are synced factory-wide, so a legacy name
    // lives on every device forever. Any entry that matches NO pool name is a
    // stale reference too — offer it here (applyRecipeNameMerge already
    // rewrites + tombstones these lists). Factory MIX_SEED names are excluded
    // on the Mix Plan tab: they are locally seeded (not stale) and would be
    // re-seeded if merged away.
    const legacyList =
      cat === "dough" ? doughRecipeNames
      : cat === "sauce" ? frontlineRecipeNames
      : cat === "cheese" ? cheeseRecipeNames
      : mixRecipeNames;
    const staleLocal = legacyList.filter((n) => {
      const key = n.trim().toLowerCase();
      return key && !poolCi.has(key);
    });
    return dedupSorted([...stale, ...staleLocal]);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mergeCategory, serverDoughNames, serverSauceNames, serverCheeseNames, serverMixNames, doughRecipeNames, frontlineRecipeNames, cheeseRecipeNames, mixRecipeNames]);

  // Case-insensitive membership for the "old reference" label in the picker.
  const mergeStaleCi = useMemo(
    () => new Set(mergeStaleNames.map((n) => n.trim().toLowerCase())),
    [mergeStaleNames],
  );

  const mergeUniverse = useMemo(() => {
    switch (mergeCategory) {
      // The four recipe categories merge that category's RECIPE NAMES (the
      // picklist labels), not ingredient names. Mixes, Dough, Sauce and Cheese
      // are all server-backed master-data now (their sections under Manage
      // Lists), so each picker shows the SAME live server pool — not the dormant
      // local `mixRecipeNames` / `doughRecipeNames` / `frontlineRecipeNames`
      // lists, which held legacy names that no longer appear in the app. Every
      // recipe tab ALSO unions in the stale referenced names (mergeStaleNames)
      // so leftover names in any category can be merged away.
      case "mixes": return dedupSorted([...serverMixNames, ...mergeStaleNames]);
      case "dough": return dedupSorted([...serverDoughNames, ...mergeStaleNames]);
      case "sauce": return dedupSorted([...serverSauceNames, ...mergeStaleNames]);
      case "cheese": {
        // A name that also lives in the user Mix list is a mix, not a cheese
        // recipe, so keep the Cheese tab mix-free.
        const mixNameSet = new Set(serverMixNames.map((n) => n.toLowerCase()));
        return dedupSorted([
          ...serverCheeseNames.filter((n) => !mixNameSet.has(n.toLowerCase())),
          ...mergeStaleNames,
        ]);
      }
      case "brandflavor":
        return dedupSorted(mergeBfMode === "brands" ? brands : (brandFlavors[mergeBfBrand] ?? []));
      case "ingredients":
      default: {
        // Individual + pep ingredient names, MINUS any name that is a recipe
        // name in another category (those are merged on their own tabs), so the
        // Ingredients tab stays real-ingredient-only. The mix set must be the
        // FULL mix-name universe (every factory MIX_SEED name + user-added),
        // NOT `allMixRecipeOptions` — that one is scoped to the current run's
        // brand/flavor, so mix names for other brands/flavors would leak in.
        const recipeNameSet = new Set(
          [
            ...serverDoughNames,
            ...serverSauceNames,
            ...doughRecipeNames,
            ...frontlineRecipeNames,
            ...serverCheeseNames,
            ...cheeseRecipeNames,
            ...MIX_SEED.mixRecipeNames,
            ...mixRecipeNames,
            ...serverMixNames,
          ].map((n) => n.toLowerCase()),
        );
        // Stray mix/cheese-recipe names (often ending in "Mix") get imported
        // into `ingredientTypes` with spellings that don't exactly match any
        // recipe list, so the exact-match set above misses them. Treat any name
        // ending in "mix" as a recipe name too, EXCEPT genuine ingredients that
        // legitimately end in "mix" (allowlisted below, e.g. "Hot Giardiniera
        // Mix"). See `.local/parity-pause-log.md`.
        const realIngredientAllowlist = new Set(
          // "mix"/"cheese" are the generic applicator types (Mix/Cheese cards
          // gate on them) — legitimate dropdown entries, never stray names.
          ["mix", "cheese", ...DEFAULT_INGREDIENT_TYPES, ...MIX_SEED.frontlineIngredients, ...pepTypes].map((n) =>
            n.toLowerCase(),
          ),
        );
        return dedupSorted(
          // The unified universe (catalog + every server pool's recipe rows +
          // all local lists) so every ingredient used anywhere is mergeable —
          // still minus recipe names and stray mix names (same filters as
          // before the universe expanded).
          unifiedIngredientUniverse.filter(
            (n) => !recipeNameSet.has(n.toLowerCase()) && !isStrayMixName(n, realIngredientAllowlist),
          ),
        );
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mergeCategory, mergeBfMode, mergeBfBrand, brands, brandFlavors, ingredientTypes, pepTypes, unifiedIngredientUniverse, serverDoughNames, serverSauceNames, doughRecipeNames, frontlineRecipeNames, serverCheeseNames, cheeseRecipeNames, mixRecipeNames, serverMixNames, allMixRecipeOptions, mergeStaleNames]);

  // Recipe categories are merged by recipe NAME (not ingredient name).
  const isRecipeNameCategory =
    mergeCategory === "dough" || mergeCategory === "sauce" || mergeCategory === "cheese" || mergeCategory === "mixes";

  // Human label for the active recipe tab's real-recipe home (Manage Lists
  // section) — used by the "old reference" tag and the cleanup panel copy.
  const mergePoolLabel =
    mergeCategory === "mixes" ? "Mix Recipes"
    : mergeCategory === "dough" ? "Dough Recipes"
    : mergeCategory === "sauce" ? "Sauce Recipes"
    : "Cheese Recipes";

  // One suggested cleanup per stale reference: the closest REAL pool recipe
  // via the shared near-duplicate matcher (ambiguity-guarded — no single safe
  // match ⇒ no suggestion). Suggestions only PRE-FILL the merge pair; the user
  // confirms each one through the normal merge flow, never auto-applied.
  const staleCleanupSuggestions = useMemo(() => {
    if (!isRecipeNameCategory || mergeStaleNames.length === 0) return [];
    const poolNames =
      mergeCategory === "dough" ? serverDoughNames
      : mergeCategory === "sauce" ? serverSauceNames
      : mergeCategory === "mixes" ? serverMixNames
      : serverCheeseNames;
    return buildStaleCleanupSuggestions(mergeStaleNames, poolNames);
  }, [isRecipeNameCategory, mergeCategory, mergeStaleNames, serverDoughNames, serverSauceNames, serverMixNames, serverCheeseNames]);

  // Which merge-suggest category/brand/pool the AI scan and learned-alias
  // memory should use for the currently active tab. Each tab scans and stores
  // ONLY its own name pool so a suggestion, alias, or denial never leaks across
  // tabs. "ingredients" intentionally keeps scanning the cross-category
  // mergeFullUniverse (unchanged prior behavior); every recipe-name tab scans
  // just its own recipe-name list (mergeUniverse, already scoped); Brand/Flavor
  // scans brands or one brand's flavors depending on the active sub-mode.
  const mergeSuggestScope = useMemo((): {
    category: MergeSuggestCategory;
    brand?: string;
    universe: string[];
  } => {
    switch (mergeCategory) {
      case "mixes":
        return { category: "mixes", universe: mergeUniverse };
      case "dough":
        return { category: "dough", universe: mergeUniverse };
      case "sauce":
        return { category: "sauce", universe: mergeUniverse };
      case "cheese":
        return { category: "cheese", universe: mergeUniverse };
      case "brandflavor":
        return mergeBfMode === "brands"
          ? { category: "brand", universe: mergeUniverse }
          : { category: "flavor", brand: mergeBfBrand, universe: mergeUniverse };
      case "ingredients":
      default:
        return { category: "ingredient", universe: mergeFullUniverse };
    }
  }, [mergeCategory, mergeBfMode, mergeBfBrand, mergeUniverse, mergeFullUniverse]);

  // Same universe, ordered closest-match-first so likely duplicates surface at the
  // top. When sources are selected, rank by best similarity to any selected
  // source; otherwise fall back to similarity against the typed target; otherwise
  // alphabetical. Reuses the shared name-similarity helper.
  const mergeUniverseRanked = useMemo(() => {
    const probes = [...mergeSources, mergeTarget.trim()].filter(Boolean);
    if (probes.length === 0) return mergeUniverse;
    return mergeUniverse
      .map((name, i) => ({
        name,
        i,
        s: Math.max(...probes.map((p) => scoreNameMatch(p, name))),
      }))
      .sort((a, b) => b.s - a.s || a.i - b.i)
      .map((x) => x.name);
  }, [mergeUniverse, mergeSources, mergeTarget]);

  // Target picklist. For mixes it unions the factory-preset names so a user-added
  // duplicate can be folded into a canonical factory recipe name; otherwise it's
  // the ranked category universe. The currently-checked sources are hoisted to the
  // top so the user can quickly pick one of the names they selected as the one to
  // keep (the common case) instead of hunting for it in the full list.
  const mergeTargetOptions = useMemo(
    () => {
      const base = mergeCategory === "mixes" ? dedupSorted([...serverMixNames, ...allMixRecipeOptions]) : mergeUniverseRanked;
      if (mergeSources.length === 0) return base;
      const chosen = new Set(mergeSources);
      return [...mergeSources, ...base.filter(n => !chosen.has(n))];
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [mergeCategory, serverMixNames, allMixRecipeOptions, mergeUniverseRanked, mergeSources],
  );

  // Gather every value surface a merge would touch, so the confirmation preview
  // can count affected references. Mirrors buildSyncPayload's localStorage scan.
  function collectMergeSurfaces() {
    // Die types are intentionally excluded — they don't participate in merges.
    const lists = [
      ingredientTypes,
      cheeseIngredients,
      doughIngredients,
      frontlineIngredients,
      mixIngredients,
      pepTypes,
    ];
    const settingsObjects: Record<string, unknown>[] = [];
    for (const run of dayStateRef.current.runs) {
      const vals = run.id === currentRunId ? form.getValues() : loadRunValues(run.id);
      settingsObjects.push(vals as unknown as Record<string, unknown>);
    }
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (!key) continue;
      if (key.startsWith("run-calc-profile-") || key.startsWith("run-calc-crust-profile-")) {
        try {
          const obj = JSON.parse(localStorage.getItem(key) ?? "null");
          if (obj && typeof obj === "object") settingsObjects.push(obj as Record<string, unknown>);
        } catch {}
      }
    }
    for (const day of loadHistory()) {
      for (const vals of Object.values(day.runValues ?? {})) {
        settingsObjects.push(vals as unknown as Record<string, unknown>);
      }
    }
    const doughPresets = loadDoughRecipePresets();
    const doughRows: Record<string, { ingredient?: unknown }[]> = {};
    for (const [n, p] of Object.entries(doughPresets)) doughRows[n] = p.rows ?? [];
    const presetMaps = [doughRows, loadFrontlineRecipePresets(), loadCheeseRecipePresets()];
    // Server master-data pools (cheese recipes, mixes, dough/sauce recipes) —
    // the merge re-points their ingredient rows case-insensitively via the
    // repoint helpers, so the preview must count them too or a name that lives
    // only in factory recipes shows a misleading "0 references".
    const ciRowLists: { ingredient?: unknown }[][] = [
      ...cheeseRecipesList.map((r) => r.components ?? []),
      ...mixes.map((m) => m.components ?? []),
      ...doughRecipesList.map((r) => r.components ?? []),
      ...sauceRecipesList.map((r) => r.components ?? []),
    ];
    return { lists, settingsObjects, presetMaps, ciRowLists };
  }

  // Recipe-name preview surfaces: the category's name list, the settings objects
  // (runs/profiles/templates/history) whose recipe-name selection fields get
  // re-pointed, and the category's recipe-preset map (its KEYS get folded).
  function collectRecipeNameSurfaces(category: RecipeNameMergeCategory) {
    const listMap: Record<RecipeNameMergeCategory, string[]> = {
      dough: serverDoughNames,
      sauce: serverSauceNames,
      cheese: serverCheeseNames,
      mixes: serverMixNames,
    };
    const { settingsObjects } = collectMergeSurfaces();
    const presetKeyMaps: Record<string, unknown>[] =
      category === "dough" ? [loadDoughRecipePresets()]
      : category === "sauce" ? [loadFrontlineRecipePresets()]
      : category === "cheese" ? [loadCheeseRecipePresets()]
      : [];
    return { lists: [listMap[category]], settingsObjects, presetKeyMaps };
  }

  const mergeMap: MergeMap = buildMergeMap(mergeSources, mergeTarget);
  const mergePreviewCount = useMemo(() => {
    if (Object.keys(mergeMap).length === 0) return 0;
    try {
      if (isRecipeNameCategory) {
        return countRecipeNameReferences(
          mergeMap,
          RECIPE_NAME_FIELDS_BY_CATEGORY[mergeCategory as RecipeNameMergeCategory],
          collectRecipeNameSurfaces(mergeCategory as RecipeNameMergeCategory),
        );
      }
      return countMergeReferences(mergeMap, collectMergeSurfaces());
    } catch { return 0; }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mergeSources, mergeTarget, mergeCategory, cheeseRecipesList, mixes, doughRecipesList, sauceRecipesList]);

  function toggleMergeSource(name: string) {
    setMergeError("");
    setMergeConfirming(false);
    setMergeSources(prev =>
      prev.includes(name) ? prev.filter(n => n !== name) : [...prev, name],
    );
  }

  function resetMergeForm() {
    setMergeSources([]);
    setMergeTarget("");
    setMergeConfirming(false);
    setMergeBusy(false);
    setMergeError("");
  }

  // Ask for duplicate-group suggestions: combines AI clustering with learned
  // "previously merged" aliases. Results are reviewed (never auto-applied);
  // each group's "Load" pre-fills the manual merge form for inspection, while
  // "Apply" merges it directly through the same destructive merge path.
  async function handleSuggestMerges(fromImport = false, forceRefresh = false): Promise<number> {
    if (!fromImport) setMergeFromImport(false);
    // The import-triggered auto-scan always lands on (and scans) the
    // Ingredients tab — read from the closured `mergeFullUniverse` directly
    // rather than `mergeSuggestScope`, since `setMergeCategory("ingredients")`
    // in the caller effect hasn't re-rendered yet and the scope memo would
    // still reflect whatever tab was active before.
    const scope = fromImport
      ? { category: "ingredient" as const, universe: mergeFullUniverse }
      : mergeSuggestScope;
    const request = mergeSuggestRequestRef.current;
    request.controller?.abort();
    const controller = new AbortController();
    request.controller = controller;
    const generation = ++request.generation;
    setMergeSuggestBusy(true);
    setMergeSuggestError("");
    setMergeSuggestNote("");
    setMergeSuggestRan(true);
    try {
      const { suggestions, usedAi, error } = await suggestMerges(
        scope.universe,
        scope.category,
        scope.brand,
        // Known brands power the deterministic cross-brand guard: a suggestion
        // pairing names that mention DIFFERENT brands ("Lowes …" vs "Bashas …")
        // is dropped no matter what the AI said.
        brands,
        { signal: controller.signal, forceRefresh },
      );
      if (!isCurrentMergeSuggestionRequest(generation, request.generation, controller.signal)) return 0;
      setMergeSuggestions(suggestions);
      setMergeSuggestSelected(new Set());
      if (!usedAi && error) {
        setMergeSuggestError(
          `AI unavailable (${error}). Showing look-alike and previously-merged matches only.`,
        );
      }
      if (usedAi && suggestions.length === 0) {
        setMergeSuggestNote("No duplicate groups found.");
      }
      return suggestions.length;
    } catch (e) {
      if (!isCurrentMergeSuggestionRequest(generation, request.generation, controller.signal)) return 0;
      setMergeSuggestions([]);
      setMergeSuggestSelected(new Set());
      setMergeSuggestError(e instanceof Error ? e.message : "Couldn't get suggestions.");
      return 0;
    } finally {
      if (isCurrentMergeSuggestionRequest(generation, request.generation)) {
        request.controller = null;
        setMergeSuggestBusy(false);
      }
    }
  }

  // Suggestions are deliberately lazy: opening the merge review is the only
  // automatic trigger. Imports must not start an expensive AI request behind
  // the manager's back, and leaving the surface cancels any active request.
  useEffect(() => {
    if (manageCategory === "merge") {
      void handleSuggestMerges();
    } else {
      mergeSuggestRequestRef.current.controller?.abort();
    }
    // The request snapshots the current merge scope when the surface opens.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [manageCategory]);

  // Pre-fill the manual merge form from a suggested group so the user can review
  // and tweak the source selection before confirming. Names are snapped to the
  // universe's exact spelling so the source checkboxes actually tick (AI/learned
  // suggestion names can differ in case), and the form (which sits below the
  // suggestion list) is scrolled into view so it's obvious Load did something.
  function loadMergeSuggestion(s: MergeSuggestion) {
    setMergeError("");
    setMergeConfirming(false);
    setMergeFromImport(false);
    // Suggestions shown are always scoped to the currently active tab (each
    // scan uses that tab's own pool), so snap names against that same pool —
    // never force a tab switch.
    const canon = (n: string) =>
      mergeSuggestScope.universe.find((u) => u.toLowerCase() === n.trim().toLowerCase()) ??
      n.trim();
    const tgt = canon(s.target);
    const seen = new Set<string>();
    const srcs: string[] = [];
    for (const raw of s.sources) {
      const n = canon(raw);
      const key = n.toLowerCase();
      if (n.toLowerCase() === tgt.toLowerCase() || seen.has(key)) continue;
      seen.add(key);
      srcs.push(n);
    }
    setMergeTarget(tgt);
    setMergeSources(srcs);
    requestAnimationFrame(() =>
      mergeFormRef.current?.scrollIntoView({ behavior: "smooth", block: "start" }),
    );
  }

  // Stable identity for a suggestion group, used for batch-apply checkboxes.
  // Sources are sorted and every part URI-encoded so names containing the
  // delimiter can't collide across groups.
  function mergeSuggestKey(s: MergeSuggestion): string {
    const parts = s.sources
      .filter((n) => n !== s.target)
      .map((n) => encodeURIComponent(n))
      .sort();
    return `${encodeURIComponent(s.target)}::${parts.join("|")}`;
  }

  function toggleMergeSuggestSelected(s: ReviewedMergeSuggestion) {
    const key = mergeSuggestKey(s);
    setMergeSuggestSelected((prev) => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });
  }

  // Apply a suggested group directly through the destructive merge path. On
  // success drop just this suggestion so the user can keep working through the
  // rest of the list (the panel stays open — no reload).
  async function applyMergeSuggestion(s: ReviewedMergeSuggestion): Promise<boolean> {
    const sources = s.sources.filter((n) => n !== s.target);
    if (sources.length === 0) return false;
    setMergeFromImport(false);
    const ok = mergeCategory === "brandflavor"
      ? await handleApplyBrandFlavorMerge(sources, s.target)
      : isRecipeNameCategory
      ? await handleApplyRecipeNameMerge(mergeCategory as RecipeNameMergeCategory, sources, s.target)
      : await handleApplyMerge(sources, s.target);
    if (ok) setMergeSuggestions((prev) => prev.filter((x) => x !== s));
    return ok;
  }

  // Batch apply: run each checked group through the SAME per-group merge path,
  // strictly one at a time (each merge rewrites lists + pushes sync; running
  // them concurrently would race). Stops on the first failure so the error for
  // that group stays visible and the remaining checked groups are untouched.
  async function applySelectedSuggestions() {
    const chosen = mergeSuggestions.filter((s) => mergeSuggestSelected.has(mergeSuggestKey(s)));
    if (chosen.length === 0 || mergeBatchBusy) return;
    setMergeBatchBusy(true);
    try {
      for (const s of chosen) {
        const ok = await applyMergeSuggestion(s);
        if (!ok) break;
        setMergeSuggestSelected((prev) => {
          const next = new Set(prev);
          next.delete(mergeSuggestKey(s));
          return next;
        });
      }
    } finally {
      setMergeBatchBusy(false);
    }
  }

  // Ignore a suggested group: persist the {target, source} pairs as denied so
  // the suggester never proposes them again (factory-wide), then drop it from
  // the open list. Persisting is best-effort — even if the POST fails the user
  // still gets the suggestion out of their way for this session.
  async function ignoreMergeSuggestion(s: ReviewedMergeSuggestion) {
    const sources = s.sources.filter((n) => n !== s.target);
    if (sources.length === 0) return;
    setMergeFromImport(false);
    setMergeSuggestions((prev) => prev.filter((x) => x !== s));
    const scope = mergeSuggestScope;
    try {
      await denyMerge(s.target, sources, scope.category, scope.brand);
    } catch {
      // Non-fatal: the suggestion is already hidden for this session; it may
      // reappear on a later scan if the deny didn't persist.
    }
  }

  async function handleApplyMerge(sourcesArg?: string[], targetArg?: string): Promise<boolean> {
    const srcs = sourcesArg ?? mergeSources;
    const tgt = targetArg ?? mergeTarget;
    const map = buildMergeMap(srcs, tgt);
    if (Object.keys(map).length === 0) {
      setMergeError("Pick at least one source and a different target.");
      return false;
    }
    setMergeBusy(true);
    setMergeError("");
    // Snapshot master-data BEFORE the merge rewrites localStorage, so the change
    // can be recorded for undo on success. Separate inventory products are
    // independent warehouse records and are intentionally not folded here.
    const mergeBefore = captureMasterDataSnapshot();
    try {
      // Rewrite every localStorage surface, then refresh React state in place so
      // the merged data shows immediately and the live-sync push carries the
      // merged lists — without tearing down the open Merge panel via a reload.
      applyIngredientMerge(map);
      void mergeCatalogEntries(srcs, tgt);
      // Persist the merged-away source names to the DURABLE factory-wide
      // tombstone (best effort). Unlike the per-day sync blob, this survives a
      // day boundary and reaches a device that was offline during the merge, so
      // the merged names never resurface. Targets (a source mapping to itself)
      // are never tombstoned.
      {
        const tombTargets = new Set(Object.values(map).map(t => t.trim().toLowerCase()));
        const tombSources = Object.keys(map).filter(s => !tombTargets.has(s.trim().toLowerCase()));
        void saveMergedAwayNames(tombSources).catch(() => {});
      }
      // Persist the confirmed merge as factory-wide learned aliases (best
      // effort): feeds the AI suggester next time and powers "previously
      // merged" suggestions. Awaited so the POST completes before we push.
      try {
        await saveMergeAliases(collectMergeAliases(srcs, tgt));
      } catch {
        // Non-fatal: the merge itself already succeeded; learning is additive.
      }
      // Also learn spec-import INGREDIENT aliases (all three kinds — the
      // Ingredients merge tab is category-agnostic and the same physical
      // ingredient can appear in dough, sauce and cheese recipe rows) so a
      // spec-sheet re-import maps the merged-away row names onto the survivor
      // instead of resurrecting them. Best-effort like the other learns.
      try {
        await learnIngredientChangeAliases(srcs, tgt);
      } catch {
        // Non-fatal: the next re-import just re-offers the old name.
      }
      // Also record each confirmed source→target as a factory-wide correction
      // (ingredient domain) so every other name-resolving AI helper honors it.
      void saveAiCorrections(
        srcs
          .filter((src) => src.trim() && src.trim().toLowerCase() !== tgt.trim().toLowerCase())
          .map((src) => ({ domain: "ingredient", fromText: src, toText: tgt })),
      );
      // Refresh all React surfaces the merge rewrote, in place, BEFORE pushing.
      // This resets the current-run form to the merged values, so the sync
      // payload below (which serializes the active run from form.getValues())
      // ships merged names rather than the stale pre-merge ones.
      refreshAfterMerge();
      // Push the merged payload (with its mergedAway tombstones) to the server
      // immediately. Otherwise an incoming sync-pull could race ahead of the
      // debounced push and the additive list-union re-adds the merged-away names
      // from the still-stale server copy. Best-effort: the local tombstone filter
      // is the backstop if this push fails.
      try {
        await pushTodayCanonical(buildSyncPayload(loadDayState()));
      } catch {
        // Non-fatal: tombstones are persisted locally.
      }
      // Dough/sauce/cheese/mix recipes are server-backed master-data (their own
      // tables, NOT in day-state sync), and their component rows store ingredient
      // NAMES. The rewrites above only touched local lists/presets/runs, so those
      // server recipes still name the merged-away ingredient — it would resurface
      // when a run hydrates rows from the pool (and consume inventory under the
      // old name). Re-point any affected server recipes to the target so the
      // merge is complete everywhere, mirroring the brand/flavor merge. Each
      // block is best-effort (writes need manage-inventory) and updates the
      // React-Query cache so the merged names show without a refetch.
      try {
        const cheese = await fetchCheeseRecipes();
        const changed = repointCheeseRecipeIngredients(cheese, srcs, tgt);
        if (changed.length > 0) {
          const saved = await saveCheeseRecipes(changed);
          cycleCountQc.setQueryData(["cheeseRecipes"], saved);
        }
      } catch {
        // Non-fatal: the local merge already succeeded.
      }
      try {
        const mixesList = await fetchMixes();
        const changed = repointMixIngredients(mixesList, srcs, tgt);
        if (changed.length > 0) {
          const saved = await saveMixes(changed);
          cycleCountQc.setQueryData(["mixes"], saved);
        }
      } catch {
        // Non-fatal: the local merge already succeeded.
      }
      for (const kind of ["dough", "sauce"] as const) {
        try {
          const recipes = await fetchNamedRecipes(kind);
          const changed = repointNamedRecipeIngredients(recipes, srcs, tgt);
          if (changed.length > 0) {
            const saved = await saveNamedRecipes(kind, changed);
            cycleCountQc.setQueryData(
              [kind === "dough" ? "doughRecipes" : "sauceRecipes"],
              saved,
            );
          }
        } catch {
          // Non-fatal: the local merge already succeeded.
        }
      }
      // Clear the merge form. The panel stays open so the user can apply more
      // suggestions.
      resetMergeForm();
      // Record the merge in the local undo trail (no-op-safe: skipped if nothing
      // actually changed). Recorded last so a failed merge above never logs.
      noteChange(
        "merge",
        `Merged ${srcs.filter((s) => s.trim()).map((s) => `"${s}"`).join(", ")} into "${tgt}"`,
        mergeBefore,
      );
      setMergeBusy(false);
      return true;
    } catch (e) {
      setMergeBusy(false);
      setMergeError(e instanceof Error ? e.message : "Merge failed. Please try again.");
      return false;
    }
  }

  // Fold one or more source brands into a target brand: union their flavors into
  // the target, drop the source brands (tombstoned so the additive sync union
  // can't resurrect them), and re-point today's runs from a merged-away brand to
  // the target. Mirrors renameBrand's surface coverage (master lists + open
  // runs); brands carry no inventory, so nothing is folded there. State writes
  // are synchronous to localStorage so the caller's immediate sync push ships the
  // merged data.
  function mergeBrands(sources: string[], target: string) {
    const tgt = target.trim();
    if (!tgt) return;
    const srcSet = new Set(
      sources.map((s) => s.trim().toLowerCase()).filter((s) => s && s !== tgt.toLowerCase()),
    );
    if (srcSet.size === 0) return;
    // Union every merged-away brand's flavors into the target brand.
    const nextFlavors = { ...brandFlavors };
    const targetFlavors = new Set(nextFlavors[tgt] ?? []);
    for (const b of Object.keys(nextFlavors)) {
      if (srcSet.has(b.toLowerCase())) {
        for (const f of nextFlavors[b] ?? []) targetFlavors.add(f);
        delete nextFlavors[b];
      }
    }
    nextFlavors[tgt] = [...targetFlavors].sort((a, b) => a.localeCompare(b));
    setBrandFlavors(nextFlavors);
    saveBrandFlavors(nextFlavors);
    // Brand list: drop sources, keep the target, sort.
    let nextBrands = brands.filter((b) => !srcSet.has(b.toLowerCase()));
    if (!nextBrands.some((b) => b.toLowerCase() === tgt.toLowerCase())) nextBrands = [...nextBrands, tgt];
    nextBrands = nextBrands.sort((a, b) => a.localeCompare(b));
    setBrands(nextBrands);
    saveList(BRANDS_KEY, nextBrands);
    // Tombstone the merged-away brand names (flavors moved to the target, so their
    // source-brand flavor namespaces need no tombstones).
    for (const b of brands) if (srcSet.has(b.toLowerCase())) tombstoneDeleted("brands", b);
    // Re-point today's runs from a merged-away brand to the target.
    const ds = dayStateRef.current;
    const updatedRuns = ds.runs.map((r) =>
      srcSet.has((r.brand ?? "").toLowerCase()) ? { ...r, brand: tgt } : r,
    );
    const newDs = { ...ds, runs: updatedRuns };
    setDayState(newDs);
    saveDayState(newDs);
  }

  // Fold one or more source flavors into a target flavor WITHIN a single brand:
  // rewrite that brand's flavor list (sources tombstoned) and re-point today's
  // runs for that brand from a merged-away flavor to the target.
  function mergeFlavors(brand: string, sources: string[], target: string) {
    const b = brand.trim();
    const tgt = target.trim();
    if (!b || !tgt) return;
    const current = brandFlavors[b] ?? [];
    const srcSet = new Set(
      sources.map((s) => s.trim().toLowerCase()).filter((s) => s && s !== tgt.toLowerCase()),
    );
    if (srcSet.size === 0) return;
    let nextList = current.filter((f) => !srcSet.has(f.toLowerCase()));
    if (!nextList.some((f) => f.toLowerCase() === tgt.toLowerCase())) nextList = [...nextList, tgt];
    nextList = nextList.sort((a, b) => a.localeCompare(b));
    const nextFlavors = { ...brandFlavors, [b]: nextList };
    setBrandFlavors(nextFlavors);
    saveBrandFlavors(nextFlavors);
    const ns = flavorNamespace(b);
    for (const f of current) if (srcSet.has(f.toLowerCase())) tombstoneDeleted(ns, f);
    const ds = dayStateRef.current;
    const updatedRuns = ds.runs.map((r) =>
      r.brand === b && srcSet.has((r.flavor ?? "").toLowerCase()) ? { ...r, flavor: tgt } : r,
    );
    const newDs = { ...ds, runs: updatedRuns };
    setDayState(newDs);
    saveDayState(newDs);
  }

  // Apply a brand or flavor merge from the manual picker, then push the merged
  // payload (with its tombstones) immediately so an incoming sync-pull can't
  // re-add the merged-away names via the additive union — mirrors handleApplyMerge.
  async function handleApplyBrandFlavorMerge(
    sourcesArg?: string[],
    targetArg?: string,
  ): Promise<boolean> {
    const map = buildMergeMap(sourcesArg ?? mergeSources, targetArg ?? mergeTarget);
    const srcs = Object.keys(map);
    const tgt = (targetArg ?? mergeTarget).trim();
    if (srcs.length === 0) {
      setMergeError("Pick at least one source and a different target.");
      return false;
    }
    if (mergeBfMode === "flavors" && !mergeBfBrand.trim()) {
      setMergeError("Pick a brand first.");
      return false;
    }
    setMergeBusy(true);
    setMergeError("");
    const before = captureMasterDataSnapshot();
    try {
      if (mergeBfMode === "brands") mergeBrands(srcs, tgt);
      else mergeFlavors(mergeBfBrand, srcs, tgt);
      // Record each confirmed source→target as a factory-wide AI correction
      // (brand or flavor domain) so every name-resolving AI feature knows the
      // merged-away names map to the survivor. Best-effort, fire-and-forget.
      void saveAiCorrections(
        srcs
          .filter((src) => src.trim() && src.trim().toLowerCase() !== tgt.trim().toLowerCase())
          .map((src) => ({
            domain: mergeBfMode === "brands" ? "brand" : "flavor",
            fromText: src,
            toText: tgt,
          })),
      );
      // Persist the confirmed merge as a learned alias, scoped to this
      // category ("brand", or "flavor" scoped to the one brand it happened
      // within) so it feeds the AI suggester and "previously merged" list for
      // this tab only — never leaking into another brand's flavor pool.
      try {
        await saveMergeAliases(
          collectMergeAliases(srcs, tgt),
          mergeBfMode === "brands" ? "brand" : "flavor",
          mergeBfMode === "flavors" ? mergeBfBrand : undefined,
        );
      } catch {
        // Non-fatal: the merge itself already succeeded; learning is additive.
      }
      // ALSO learn a spec-import alias: the Excel importers (spec, premix,
      // cheese) canonicalize through the spec-import alias store, not the merge
      // suggester's — without this, re-importing an old workbook resurrects the
      // merged-away brand/flavor as if it were new.
      try {
        await learnSpecImportAliasesForNameChange(
          mergeBfMode === "brands" ? "brand" : "flavor",
          srcs,
          tgt,
          mergeBfMode === "flavors" ? mergeBfBrand : undefined,
        );
      } catch {
        // Non-fatal: the next re-import just shows the old name for review.
      }
      try {
        await pushTodayCanonical(buildSyncPayload(loadDayState()));
      } catch {
        // Non-fatal: tombstones are persisted locally.
      }
      // Cheese recipes and mixes are server-backed master-data (NOT in day-state
      // sync), so a brand/flavor merge won't touch them — re-point any that still
      // name a merged-away brand (or flavor, within the brand) so they stop
      // showing under the old label in the Cheese Recipes / Mixes managers.
      try {
        const cheese = await fetchCheeseRecipes();
        const changed =
          mergeBfMode === "brands"
            ? repointCheeseRecipesForBrandMerge(cheese, srcs, tgt)
            : repointCheeseRecipesForFlavorMerge(cheese, mergeBfBrand, srcs, tgt);
        if (changed.length > 0) {
          const saved = await saveCheeseRecipes(changed);
          cycleCountQc.setQueryData(["cheeseRecipes"], saved);
        }
      } catch {
        // Non-fatal: the merge itself already succeeded.
      }
      try {
        const mixesList = await fetchMixes();
        const changed =
          mergeBfMode === "brands"
            ? repointMixesForBrandMerge(mixesList, srcs, tgt)
            : repointMixesForFlavorMerge(mixesList, mergeBfBrand, srcs, tgt);
        if (changed.length > 0) {
          const saved = await saveMixes(changed);
          cycleCountQc.setQueryData(["mixes"], saved);
        }
      } catch {
        // Non-fatal: the merge itself already succeeded.
      }
      resetMergeForm();
      const label = mergeBfMode === "brands" ? "brand" : "flavor";
      noteChange(
        "merge",
        `Merged ${label}s ${srcs.map((s) => `"${s}"`).join(", ")} into "${tgt}"` +
          (mergeBfMode === "flavors" ? ` (${mergeBfBrand})` : ""),
        before,
      );
      setMergeBusy(false);
      return true;
    } catch (e) {
      setMergeBusy(false);
      setMergeError(e instanceof Error ? e.message : "Merge failed. Please try again.");
      return false;
    }
  }

  // Merge one or more source RECIPE NAMES into a target within a single category
  // (dough/sauce/cheese/mixes). Unlike an ingredient merge this touches no
  // inventory — it only re-points recipe-name selection fields, folds the name
  // list + recipe presets, and tombstones the merged-away names. Mirrors
  // handleApplyMerge's snapshot → rewrite → refresh → push → note flow.
  async function handleApplyRecipeNameMerge(
    category: RecipeNameMergeCategory,
    sourcesArg?: string[],
    targetArg?: string,
  ): Promise<boolean> {
    const sourcesAll = sourcesArg ?? mergeSources;
    const tgt = targetArg ?? mergeTarget;
    // Guardrail: mergeable mix sources are real (server) mix names OR stale
    // references (names in NO pool — leftover picks the merge cleans up).
    // Factory MIX_SEED names stay excluded: they'd just be re-seeded locally.
    const mixSeedCi = new Set(MIX_SEED.mixRecipeNames.map((n) => n.trim().toLowerCase()));
    const rawSources = category === "mixes"
      ? sourcesAll.filter(
          (s) => serverMixNames.includes(s) || !mixSeedCi.has(s.trim().toLowerCase()),
        )
      : sourcesAll;
    const map = buildMergeMap(rawSources, tgt);
    if (Object.keys(map).length === 0) {
      setMergeError("Pick at least one source and a different target.");
      return false;
    }
    setMergeBusy(true);
    setMergeError("");
    const before = captureMasterDataSnapshot();
    try {
      // Rewrite every localStorage surface, then refresh React state in place so
      // the merged data shows immediately and the sync push carries it.
      const affectedRunIds = applyRecipeNameMerge(category, map);
      // Record each confirmed source→target as a factory-wide AI correction
      // (recipe domain) so every AI feature knows the old recipe name maps to
      // the new one. Best-effort, fire-and-forget.
      void saveAiCorrections(
        Object.keys(map)
          .filter((src) => src.trim() && src.trim().toLowerCase() !== tgt.trim().toLowerCase())
          .map((src) => ({ domain: "recipe", fromText: src, toText: tgt })),
      );
      // Persist the confirmed merge as a learned alias scoped to this recipe-
      // name category so it feeds the AI suggester and "previously merged"
      // list for this tab's own pool only.
      try {
        await saveMergeAliases(collectMergeAliases(Object.keys(map), tgt), category);
      } catch {
        // Non-fatal: the merge itself already succeeded; learning is additive.
      }
      // Advance the edit stamp on every run the merge re-pointed, so the push
      // below strictly wins the per-run lost-update guard on the server and every
      // peer. Without this, a stale remote payload carrying the pre-merge recipe
      // name at an equal/older stamp (common for unedited/imported runs at ts 0)
      // could overwrite the merged selection on the next sync pull.
      if (affectedRunIds.length > 0) {
        const stamp = Date.now();
        const upd = loadRunValuesUpdated();
        for (const id of affectedRunIds) upd[id] = stamp;
        saveRunValuesUpdated(upd);
      }
      refreshAfterMerge();
      // Push the merged payload (with its deletion tombstones) immediately so an
      // incoming sync-pull's additive union can't re-add the merged-away names.
      try {
        await pushTodayCanonical(buildSyncPayload(loadDayState()));
      } catch {
        // Non-fatal: tombstones are persisted locally.
      }
      // Dough / sauce / cheese / mix recipes are server-backed factory master-
      // data (NOT in day-state sync), and the merge picker's universe is derived
      // from those live server pools. Rewriting only localStorage above lets a
      // react-query refetch immediately resurrect the merged-away source names,
      // so delete the source recipes from the correct server pool by name (the
      // target recipe wins and is kept). Best-effort + manager-gated, mirroring
      // how handleApplyBrandFlavorMerge re-points these same pools.
      // The surviving recipe's brand (when its pool row is found below) scopes
      // the learned import alias — captured here, used after the cleanup block.
      let aliasBrandCtx: string | undefined;
      try {
        const tgtLc = tgt.trim().toLowerCase();
        const sourceNamesLc = new Set(
          Object.keys(map)
            .map((s) => s.trim().toLowerCase())
            .filter((s) => s && s !== tgtLc),
        );
        if (sourceNamesLc.size > 0) {
          // Before deleting the merged-away recipes, backfill the TARGET's
          // blank/zero/missing fields from them (blank-fill-only — real data
          // already on the target always wins). Without this, merging a real
          // recipe into a spec-import stub silently deleted the real batch
          // data from the factory-wide pool. The enriched target is SAVED
          // first; only then are the sources deleted, so a failed save keeps
          // the sources (and their data) alive.
          if (category === "cheese") {
            const pool = await fetchCheeseRecipes();
            let targetRow = pool.find((r) => r.name.trim().toLowerCase() === tgtLc);
            let sourceRows = pool.filter((r) =>
              sourceNamesLc.has(r.name.trim().toLowerCase()),
            );
            // The picked target has NO pool row (a typed/renamed name):
            // promote the richest source by RENAMING it to the target (the
            // pool upsert is id-keyed, so keeping the id renames in place).
            // Without this, deleting the sources below destroyed the only
            // copies of the recipe data — the merged recipe vanished.
            if (!targetRow && sourceRows.length > 0) {
              const best = [...sourceRows].sort(
                (a, b) => (b.components?.length ?? 0) - (a.components?.length ?? 0),
              )[0];
              targetRow = { ...best, name: tgt.trim() };
              sourceRows = sourceRows.filter((r) => r.id !== best.id);
              await saveCheeseRecipes([targetRow]);
            }
            aliasBrandCtx = targetRow?.brand?.trim() || undefined;
            if (targetRow && sourceRows.length > 0) {
              const enriched = backfillCheeseRecipeFromMergedSources(targetRow, sourceRows);
              if (enriched) await saveCheeseRecipes([enriched]);
            }
            // Fan the target's current rows out to every profile whose app{n}
            // slot was just re-pointed to the target by applyRecipeNameMerge.
            // The name fields were already rewritten; without this the profiles
            // keep the old recipe's ingredient rows under the new name.
            if (targetRow) {
              const tRows = normalizeRecipeRowsForCompare(targetRow.components);
              if (tRows.length > 0) refreshCheeseOrMixProfileRows(tgt, tRows);
            }
            const ids = sourceRows.map((r) => r.id);
            if (ids.length > 0) {
              cycleCountQc.setQueryData(["cheeseRecipes"], await deleteCheeseRecipes(ids));
            } else if (targetRow) {
              cycleCountQc.invalidateQueries({ queryKey: ["cheeseRecipes"] });
            }
          } else if (category === "mixes") {
            const pool = await fetchMixes();
            let targetRow = pool.find((m) => m.name.trim().toLowerCase() === tgtLc);
            let sourceRows = pool.filter((m) =>
              sourceNamesLc.has(m.name.trim().toLowerCase()),
            );
            // No pool row for the target name: rename the richest source to
            // the target instead of deleting every copy of the data (see the
            // cheese branch above).
            if (!targetRow && sourceRows.length > 0) {
              const best = [...sourceRows].sort(
                (a, b) => (b.components?.length ?? 0) - (a.components?.length ?? 0),
              )[0];
              targetRow = { ...best, name: tgt.trim() };
              sourceRows = sourceRows.filter((m) => m.id !== best.id);
              await saveMixes([targetRow]);
            }
            aliasBrandCtx = targetRow?.brand?.trim() || undefined;
            if (targetRow && sourceRows.length > 0) {
              const enriched = backfillMixFromMergedSources(targetRow, sourceRows);
              if (enriched) await saveMixes([enriched]);
            }
            // Fan the target mix's rows to profiles (same reason as cheese above).
            if (targetRow) {
              const tRows = normalizeRecipeRowsForCompare(targetRow.components);
              if (tRows.length > 0) refreshCheeseOrMixProfileRows(tgt, tRows);
            }
            const ids = sourceRows.map((m) => m.id);
            if (ids.length > 0) {
              cycleCountQc.setQueryData(["mixes"], await deleteMixes(ids));
            } else if (targetRow) {
              cycleCountQc.invalidateQueries({ queryKey: ["mixes"] });
            }
          } else {
            // dough | sauce — their own named-recipe pools.
            const pool = await fetchNamedRecipes(category);
            let targetRow = pool.find((r) => r.name.trim().toLowerCase() === tgtLc);
            let sourceRows = pool.filter((r) =>
              sourceNamesLc.has(r.name.trim().toLowerCase()),
            );
            // No pool row for the target name: rename the richest source to
            // the target instead of deleting every copy of the data (see the
            // cheese branch above).
            if (!targetRow && sourceRows.length > 0) {
              const best = [...sourceRows].sort(
                (a, b) => (b.components?.length ?? 0) - (a.components?.length ?? 0),
              )[0];
              targetRow = { ...best, name: tgt.trim() };
              sourceRows = sourceRows.filter((r) => r.id !== best.id);
              await saveNamedRecipes(category, [targetRow]);
            }
            if (targetRow && sourceRows.length > 0) {
              const enriched = backfillNamedRecipeFromMergedSources(targetRow, sourceRows);
              if (enriched) await saveNamedRecipes(category, [enriched]);
            }
            // Fan the target recipe's rows to every profile that now references
            // it. applyNamedPoolChange's diff path won't fire here because the
            // TARGET recipe's rows didn't change in the pool — only a source was
            // deleted. Without this, profiles keep the old source's rows under
            // the target name until the server recipe itself changes.
            if (targetRow) {
              const tRows = normalizeRecipeRowsForCompare(targetRow.components);
              if (tRows.length > 0) {
                refreshProfilesFromNamedRecipes(category as "dough" | "sauce", [
                  { name: tgt, rows: tRows },
                ]);
              }
            }
            const ids = sourceRows.map((r) => r.id);
            if (ids.length > 0) {
              cycleCountQc.setQueryData(
                [category === "dough" ? "doughRecipes" : "sauceRecipes"],
                await deleteNamedRecipes(category, ids),
              );
            } else if (targetRow) {
              cycleCountQc.invalidateQueries({
                queryKey: [category === "dough" ? "doughRecipes" : "sauceRecipes"],
              });
            }
          }
        }
      } catch {
        // Non-fatal: the local merge already succeeded; server pool cleanup is
        // best-effort (the delete endpoints are manager-gated).
      }
      // Learn spec-import aliases (old name → survivor) so a RE-IMPORT of the
      // original workbook maps onto the merged recipe instead of resurrecting
      // it — the importers canonicalize through the SpecImportAlias store, not
      // the merge-suggester aliases saved above. Mixes/cheese use the shared
      // "appType" blend namespace (brand-scoped + context-free); dough/sauce
      // use "recipeName" with the kind in context. Fire-and-forget like the
      // brand/flavor merge path — a failure never blocks the merge.
      void learnRecipeNameChangeAliases(category, Object.keys(map), tgt, aliasBrandCtx).catch(
        () => {},
      );
      resetMergeForm();
      const label =
        category === "mixes" ? "mix" : category === "sauce" ? "sauce" : category;
      noteChange(
        "merge",
        `Merged ${label} recipe ${Object.keys(map).map((s) => `"${s}"`).join(", ")} into "${tgt.trim()}"`,
        before,
      );
      setMergeBusy(false);
      return true;
    } catch (e) {
      setMergeBusy(false);
      setMergeError(e instanceof Error ? e.message : "Merge failed. Please try again.");
      return false;
    }
  }

  // Remove a stale ("old reference") recipe name outright — for names with no
  // real pool recipe behind them and no good merge target. Clears the name from
  // every surface that still references it (run link fields, profiles,
  // templates, history, legacy local name lists) and tombstones it so the
  // additive sync union can't resurrect it on other devices. Refuses pool-backed
  // names — real recipes are deleted in their Manage Lists section, not here.
  // NO spec-import alias is learned here on purpose: aliases map old→NEW name
  // and a removal has no survivor to point at. Re-import behavior: the next
  // import of a workbook carrying this name simply re-offers it as a new item
  // for manual review (create/link/skip) — it does not silently resurrect any
  // local references, since those were cleared and tombstoned above.
  async function handleRemoveStaleReference(name: string): Promise<void> {
    if (!isRecipeNameCategory) return;
    const category = mergeCategory as RecipeNameMergeCategory;
    const nameCi = name.trim().toLowerCase();
    const poolCi = new Set(
      [...serverDoughNames, ...serverSauceNames, ...serverCheeseNames, ...serverMixNames].map(
        (n) => n.trim().toLowerCase(),
      ),
    );
    if (poolCi.has(nameCi)) {
      toast({
        title: "Can't remove a real recipe here",
        description: `"${name}" exists as a recipe in Manage Lists. Delete it from its own section there instead.`,
        variant: "destructive",
      });
      return;
    }
    setMergeBusy(true);
    setMergeError("");
    const before = captureMasterDataSnapshot();
    try {
      const affectedRunIds = removeStaleRecipeReference(category, name);
      // Advance the edit stamp on every run the removal touched so the push
      // below wins the per-run lost-update guard (same reasoning as a merge —
      // otherwise a stale peer resurrects the cleared selection).
      if (affectedRunIds.length > 0) {
        const stamp = Date.now();
        const upd = loadRunValuesUpdated();
        for (const id of affectedRunIds) upd[id] = stamp;
        saveRunValuesUpdated(upd);
      }
      // Drop the removed name from any in-progress merge selection.
      setMergeSources((s) => s.filter((n) => n.trim().toLowerCase() !== nameCi));
      if (mergeTarget.trim().toLowerCase() === nameCi) setMergeTarget("");
      refreshAfterMerge();
      // Push immediately (with the deletion tombstone) so an incoming sync
      // pull's additive union can't re-add the removed name.
      try {
        await pushTodayCanonical(buildSyncPayload(loadDayState()));
      } catch {
        // Non-fatal: the tombstone is persisted locally and rides the next push.
      }
      noteChange("remove", `Removed old reference "${name}" (${mergePoolLabel})`, before);
      toast({
        title: "Old reference removed",
        description: `"${name}" was cleared from runs, saved setups, templates and history.`,
      });
    } finally {
      setMergeBusy(false);
    }
  }

  // Route the confirm button to the right merge path for the active category.
  function handleConfirmMerge(): Promise<boolean> {
    if (mergeCategory === "brandflavor") return handleApplyBrandFlavorMerge();
    if (isRecipeNameCategory) return handleApplyRecipeNameMerge(mergeCategory as RecipeNameMergeCategory);
    return handleApplyMerge();
  }

  // Switch the merge category, clearing the picker + any open AI suggestions so
  // nothing leaks across categories.
  function switchMergeCategory(cat: MergeCategory) {
    if (cat === mergeCategory) return;
    mergeSuggestRequestRef.current.controller?.abort();
    setMergeCategory(cat);
    resetMergeForm();
    setMergeSuggestions([]);
    setMergeSuggestSelected(new Set());
    setMergeSuggestRan(false);
    setMergeSuggestError("");
    setMergeSuggestNote("");
    setMergeFromImport(false);
    if (cat === "brandflavor" && !mergeBfBrand && brands.length > 0) setMergeBfBrand(brands[0]);
  }

  // Undo a master-data change (and every change made after it). Restores the
  // entry's before-snapshot, refreshes every React surface, and re-pushes the
  // restored master data to the server so the rollback propagates (and merged-
  // away names don't get resurrected by the additive sync union).
  async function handleUndoChange(entry: MasterDataChange) {
    const list = loadChangeHistory();
    const idx = list.findIndex((e) => e.id === entry.id);
    const discarded = idx === -1 ? [] : list.slice(0, idx + 1);
    const hasMerge = discarded.some((e) => e.type === "merge");
    const warn = hasMerge
      ? "\n\nNote: this reverses the ingredient names and lists, but does NOT un-fold any inventory stock that was combined by a merge. Re-check stock in Inventory."
      : "";
    const extra = discarded.length - 1;
    const tail = extra > 0 ? ` and ${extra} later change${extra === 1 ? "" : "s"}` : "";
    if (!window.confirm(`Undo "${entry.description}"${tail}?${warn}`)) return;
    setUndoBusy(true);
    try {
      const ok = undoChange(entry.id);
      if (!ok) {
        setChangeHistory(loadChangeHistory());
        return;
      }
      refreshAfterMerge();
      setChangeHistory(loadChangeHistory());
      try {
        await pushTodayCanonical(buildSyncPayload(loadDayState()));
      } catch {
        // Non-fatal: the local restore already happened; tombstones back it up.
      }
    } finally {
      setUndoBusy(false);
    }
  }

  // ── Schedule future days ────────────────────────────────────────────────────
