  const syncStatus: SyncStatus = syncPushFailed
    ? "failed"
    : syncRetryWaiting
      ? "retrying"
      : syncPendingCount > 0
      ? "syncing"
      : !isOnline || !syncConnected
        ? "delayed"
        : lastAcknowledgedAt
